<?php
namespace App\Http\Controllers;
use App\Models\{Product,Variant,ContentEntry,SourcingRequest};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Auth;
use Illuminate\Validation\Rule;
use Illuminate\Support\Str;
class Admin {
 private function authorizeAdmin(){abort_unless(Auth::user()?->role==='admin',403);}
 public function login(){return view('login');}
 public function authenticate(Request $r){$d=$r->validate(['email'=>'required|email','password'=>'required|string|max:128']);if(!Auth::attempt($d))return back()->withErrors(['email'=>'Invalid credentials.']);$r->session()->regenerate();return redirect()->route('admin');}
 public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('home');}
 public function index(){$this->authorizeAdmin();return view('admin.index',['products'=>Product::withCount('variants')->orderBy('name')->get(),'entries'=>ContentEntry::latest()->limit(100)->get(),'requests'=>SourcingRequest::with('items')->latest()->paginate(20),'generalEnquiries'=>\App\Models\GeneralEnquiry::latest()->limit(100)->get(),'media'=>\App\Models\MediaAsset::where('status','published')->orderBy('id')->get(),'types'=>array_unique(array_column(PublicSite::SECTIONS,2))]);}
 public function createProduct(Request $r){$this->authorizeAdmin();$d=$r->validate(['name'=>'required|string|max:160','category'=>'required|string|max:120','source_url'=>'nullable|url:http,https|max:1000']);$slug=Str::slug($d['name']);if(!$slug||Product::where('slug',$slug)->exists())throw \Illuminate\Validation\ValidationException::withMessages(['name'=>'Choose a unique product name.']);$p=Product::create($d+['slug'=>$slug,'status'=>'draft']);return redirect()->route('admin.product',$p);}
 public function edit(Product $product){$this->authorizeAdmin();$product->load('variants');return view('admin.product',['product'=>$product,'media'=>\App\Models\MediaAsset::where('status','published')->orderBy('id')->get()]);}
 public function save(Request $r,Product $product){$this->authorizeAdmin();$d=$r->validate(['media_asset_id'=>'nullable|exists:media_assets,id','name'=>'required|string|max:160','name_ar'=>'nullable|string|max:160','botanical_name'=>'nullable|string|max:160','description'=>'nullable|string|max:10000','description_ar'=>'nullable|string|max:10000','origin'=>'nullable|string|max:200','source_url'=>'nullable|url:http,https|max:1000','status'=>['required',Rule::in(['draft','published'])],'applications'=>'nullable|string|max:1000','aliases'=>'nullable|string|max:1000']);if($d['status']==='published')$r->validate(['approved'=>'accepted','description'=>'required|string','source_url'=>'required|url:http,https']);foreach(['applications','aliases'] as $key)$d[$key]=array_values(array_filter(array_map('trim',explode(',',$d[$key]??''))));$d['reviewed_at']=$d['status']==='published'?now():null;$product->update($d);return back()->with('message','Product updated.');}
 public function variant(Request $r,Product $product){$this->authorizeAdmin();$d=$r->validate(['sku'=>'required|string|max:100|unique:variants,sku','form'=>'required|string|max:100','grade'=>'nullable|string|max:100']);$product->variants()->create($d+['status'=>'draft']);return back();}
 public function saveVariant(Request $r,Variant $variant){$this->authorizeAdmin();$d=$r->validate(['media_asset_id'=>'nullable|exists:media_assets,id','specifications'=>'nullable|string|max:10000','packaging'=>'nullable|string|max:5000','form'=>'required|string|max:100','grade'=>'nullable|string|max:100','description'=>'nullable|string|max:3000','status'=>['required',Rule::in(['draft','published'])]]);if($d['status']==='published')$r->validate(['approved'=>'accepted']);foreach(['specifications','packaging'] as $key){$d[$key]=array_values(array_filter(array_map('trim',preg_split('/\\r?\\n/',$d[$key]??''))));}$variant->update($d);return back()->with('message','Variant updated.');}
 public function content(Request $r){$this->authorizeAdmin();$d=$r->validate(['media_asset_id'=>'nullable|exists:media_assets,id','title_ar'=>'nullable|string|max:180','body_ar'=>'nullable|string|max:30000','type'=>['required',Rule::in(array_unique(array_column(PublicSite::SECTIONS,2)))],'title'=>'required|string|max:180','body'=>'required|string|max:30000','source_url'=>'nullable|url:http,https|max:1000','event_date'=>'nullable|date','expires_at'=>'nullable|date','status'=>['required',Rule::in(['draft','published'])]]);if($d['status']==='published')$r->validate(['approved'=>'accepted']);ContentEntry::create($d+['slug'=>Str::slug($d['title']).'-'.Str::lower(Str::random(8))]);return back()->with('message','Content created.');}
 public function editContent(Request $r,ContentEntry $contentEntry){$this->authorizeAdmin();$d=$r->validate(['media_asset_id'=>'nullable|exists:media_assets,id','title_ar'=>'nullable|string|max:180','body_ar'=>'nullable|string|max:30000','title'=>'required|string|max:180','body'=>'required|string|max:30000','source_url'=>'nullable|url:http,https|max:1000','event_date'=>'nullable|date','expires_at'=>'nullable|date','status'=>'required|in:draft,published']);if($d['status']==='published')$r->validate(['approved'=>'accepted']);$contentEntry->update($d);return back()->with('message','Content updated.');}
 public function status(Request $r,SourcingRequest $sourcingRequest){$this->authorizeAdmin();$d=$r->validate(['status'=>['required',Rule::in(['new','qualified','quoted','negotiating','won','lost'])]]);$sourcingRequest->update($d);return back();}
}
